def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f'Class name must be a valid identifier: {name!r}')

    if not isinstance(fields, (list, tuple)):
        raise TypeError(f'Fields must be a list or tuple: {fields!r}')

    if not all(isinstance(f, str) and f.isidentifier() for f in fields):
        raise TypeError(f'All field names must be valid identifiers: {fields!r}')

    if not isinstance(srid_map, dict):
        raise TypeError(f'SRID map must be a dictionary: {srid_map!r}')

    namespace = {
        '__slots__': fields,
        'srid_map': srid_map
    }

    class Point:
        def __init__(self, *args):
            if len(args) != len(fields):
                raise ValueError(f'Expected {len(fields)} arguments, got {len(args)}')
            for name, value in zip(fields, args):
                setattr(self, name, value)

        def __repr__(self):
            return f"{name}({', '.join(f'{field}={getattr(self, field)!r}' for field in fields)})"

    cls = type(name, (Point,), namespace)
    return cls

