    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    try:
        if 'Broken' in getattr(sequence, '__bases__', ()):
            output.append(sequence)
            return output
    except AttributeError:
        pass

    cls = sequence.__class__
    if 'InterfaceClass' in (c.__name__ for c in cls.__mro__) or 'Implements' in (c.__name__ for c in cls.__mro__):
        output.append(sequence)
    else:
        try:
            for v in sequence:
                _normalizeargs(v, output)
        except TypeError:
            raise RuntimeError("Argument `sequence` is not iterable or does not contain valid elements")

    return output

