def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, (tuple, list)):
        raise ValueError("coord must be a tuple or list of coordinates")
    if len(coord) != len(self.edges) - 1:
        raise ValueError("coord must have the same dimensionality as the number of edges")

    # Check if the coordinate is within the histogram edges
    within_bounds = True
    for i in range(len(coord)):
        if not (self.edges[i] <= coord[i] < self.edges[i+1]):
            within_bounds = False
            break

    if within_bounds:
        # Calculate the bin indices
        bin_indices = [np.searchsorted(self.edges[i], coord[i]) - 1 for i in range(len(coord))]

        # Update the histogram
        self.values[tuple(bin_indices)] += weight

