def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        raise ValueError("Application object does not contain a valid spec.manifest")

    if not isinstance(app.spec.manifest, dict):
        raise ValueError("spec.manifest must be a dictionary")

    for resource_type, resource in app.spec.manifest.items():
        if not isinstance(resource, dict) or 'metadata' not in resource:
            continue

        resource_name = resource['metadata'].get('name')
        if not resource_name:
            continue

        resource_key = f"{resource_type}/{resource_name}"
        if resource_key not in app.observer_schema:
            app.observer_schema[resource_key] = {
                "type": "object",
                "properties": {
                    "status": {
                        "type": "object",
                        "properties": {}
                    }
                }
            }

