    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, list) or not isinstance(digests_used, list):
        raise ValueError("Both manifest_files and digests_used must be lists.")

    missing_digests = []
    for manifest_file in manifest_files:
        if not isinstance(manifest_file, dict) or 'digest' not in manifest_file:
            raise ValueError("Each manifest_file must be a dictionary with a 'digest' key.")
        digest = manifest_file['digest']
