def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        # Assuming expr is a tuple (operator, operand1, operand2)
        operator, op1, op2 = expr
        if operator == '&':
            if op1 == op2:
                return op1
            if isinstance(op2, tuple):
                sub_op, sub_op1, sub_op2 = op2
                if sub_op == '|':
                    if op1 == sub_op1:
                        return op1
                    if isinstance(sub_op2, tuple) and sub_op2[0] == '~' and sub_op2[1] == op1:
                        return ('&', op1, sub_op2[2])
        elif operator == '|':
            if op1 == op2:
                return op1
            if isinstance(op2, tuple):
                sub_op, sub_op1, sub_op2 = op2
                if sub_op == '&':
