def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("commands should be a list of strings.")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("args should be a list of strings.")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd should be a string or None.")
    if not isinstance(verbose, bool):
        raise ValueError("verbose should be a boolean.")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr should be a boolean.")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env should be a dictionary or None.")

    full_command = commands + args
    if verbose:
        print("Running command:", " ".join(full_command))

    try:
        subprocess.run(
            full_command,
            cwd=cwd,
            env=os.environ if env is None else env,
            check=True,
            stderr=subprocess.DEVNULL if hide_stderr else subprocess.STDOUT
        )
    except subprocess.CalledProcessError as e:
        print(f"Command {' '.join(full_command)} failed with return code {e.returncode}")
        raise
    except Exception as e:
        print(f"An error occurred: {str(e)}")
        raise

