def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of version directory names.")

    if not all(isinstance(v, str) for v in version_dirs):
        raise ValueError("All elements in version_dirs must be strings.")

    root_inventory = {}
    differing_digests = {}

    try:
        # Assuming there's a method to load inventory from a directory
        root_inventory = self.load_inventory(version_dirs[0])
    except Exception as e:
        raise ValueError(f"Failed to load root inventory: {e}")

    for version_dir in version_dirs:
        try:
            current_inventory = self.load_inventory(version_dir)
        except Exception as e:
            raise ValueError(f"Failed to load inventory for version {version_dir}: {e}")

        for content, digest in current_inventory.items():
            if content not in root_inventory or root_inventory[content] != digest:
                if content not in differing_digests:
                    differing_digests[content] = set()
                differing_digests[content].add(digest)

    return differing_digests

