def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        current = queue.pop()
        for subclass in current.__subclasses__():
            if subclass not in seen:
                seen.add(subclass)
                queue.append(subclass)

    return seen

