def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Get all localhost addresses including IPv4 and IPv6
        localhost_addresses = socket.getaddrinfo('localhost', None)
        # Resolve the given host
        resolved_host = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    # Extract IP addresses from resolved addresses
    localhost_ips = {addr[4][0] for addr in localhost_addresses}
    host_ips = {addr[4][0] for addr in resolved_host}

    # Check if there is any intersection
    return bool(localhost_ips.intersection(host_ips))

