def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import toml
    import yaml

    log_records = []
    config_dict = {}
    logger = logging.getLogger(__name__)

    def parse_file(filename):
        try:
            with open(filename) as fd:
                raw_config = fd.read()
            if filename.endswith('.toml'):
                return toml.loads(raw_config)
            elif filename.endswith(('.yaml', '.yml')):
                return yaml.safe_load(raw_config)
            else:
                raise ValueError(f"Unsupported file type: {filename}")
        except Exception as e:
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to parse {filename}: {e}",
                args=(),
                exc_info=True
            )
            log_records.append(record)
            return None

    for filename in config_filenames:
        if not os.path.exists(filename):
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"File not found: {filename}",
                args=(),
                exc_info=False
            )
            log_records.append(record)
            continue

        parsed_config = parse_file(filename)
        if parsed_config:
            config_dict[filename] = parsed_config

    if overrides:
        for key, value in overrides.items():
            if key in config_dict:
                config_dict[key].update(value)
            else:
                config_dict[key] = value

    if resolve_env:
        for filename, config in config_dict.items():
            try:
                config_dict[filename] = _resolve_env_variables(config)
            except Exception as e:
                record = logging.LogRecord(
                    name=logger.name,
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f"Failed to resolve environment variables in {filename}: {e}",
                    args=(),
                    exc_info=True
                )
                log_records.append(record)

    return config_dict, log_records

