def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from zope.interface import Invalid, providedBy
    import inspect

    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"{candidate} does not provide {iface}")

    required_methods = iface.names(all=True, only='method')
    required_attributes = iface.names(all=True, only='attribute')

    candidate_methods = {name: getattr(candidate, name) for name in dir(candidate) if callable(getattr(candidate, name))}
    candidate_attributes = {name: getattr(candidate, name) for name in dir(candidate) if not callable(getattr(candidate, name))}

    for name in required_methods:
        if name not in candidate_methods:
            errors.append(f"Method {name} is required by {iface} but not provided by {candidate}")

    for name in required_attributes:
        if name not in candidate_attributes:
            errors.append(f"Attribute {name} is required by {iface} but not provided by {candidate}")

    for name in required_methods:
        if name in candidate_methods:
            method = candidate_methods[name]
            required_sig = iface.get(name).__text_signature__
            try:
                if vtype is not None:
                    method_signature = inspect.signature(vtype.__dict__[name])
                else:
                    method_signature = inspect.signature(method)
                required_params = inspect.signature(eval(f"lambda {required_sig} : None")).parameters
                current_params = method_signature.parameters
                if list(current_params.keys()) != list(required_params.keys()):
                    errors.append(f"Method {name} in {iface} has signature {required_sig} but {candidate} has {method_signature}")
            except (ValueError, TypeError):
                pass

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Multiple issues found: " + ", ".join(errors))

    return True

