def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        try:
            for baseobj in base.mro():
                if isinstance(getattr(baseobj, '__class__', None), type):
                    metaclasses.add(baseobj.__class__)
        except AttributeError:
            continue

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If multiple metaclasses are found, find a common metaclass
    common_metaclass = type
    for meta in metaclasses:
        if issubclass(meta, common_metaclass):
            common_metaclass = meta
        elif not issubclass(common_metaclass, meta):
            raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

    return common_metaclass

