def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET
    try:
        # Try to parse as JSON
        data = json.loads(document)
        if "links" in data:
            return data
    except (json.JSONDecodeError, TypeError):
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ET.fromstring(document)
            xrd_ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
            hcard_url = root.find(".//xrd:Link[@rel='http://webfinger.net/rel/hcard']", xrd_ns)
            if hcard_url is not None:
                return {"hcard_url": hcard_url.get("href")}
        except (ET.ParseError, AttributeError):
            # If both JSON and XRD parsing fails, return an empty dictionary
            return {}
    return {}

