        raise TypeError("args must be an iterable of arguments")

    for arg in args:
        if not isinstance(arg, (int, float)):
            raise ValueError("Each argument must be a number")

        min_value = getattr(arg, 'min', None)
        max_value = getattr(arg, 'max', None)

        if min_value is None or max_value is None:
            raise ValueError("Each argument must have 'min' and 'max' attributes")

        if not (min_value <= arg <= max_value):
            raise ValueError(f"Argument {arg} is not within the range of {min_value} and {max_value}")

